  ('v073', 'massive', 'Có một sự MASSIVE khác biệt giữa việc ''biết code'' và ''biết code sạch''.', 'Khổng lồ, to lớn', 'beginner', 820),
  ('v074', 'neglect', 'Vì quá mải mê fix bug mà tôi NEGLECT luôn cả việc ăn tối, giờ thì đau dạ dày rồi.', 'Bỏ bê, xao nhãng', 'beginner', 855),
  ('v075', 'obvious', 'Lỗi syntax sờ sờ ra đó mà tìm mãi không thấy, đúng là OBVIOUS quá nên mới mù quáng.', 'Rõ ràng, hiển nhiên', 'beginner', 815),
  ('v076', 'persistent', 'Mấy cái quảng cáo nhà đất nó PERSISTENT gọi cho tôi cả ngày, block số này nó gọi số khác.', 'Kiên trì, dai dẳng', 'beginner', 860),
  ('v077', 'relevant', 'Nói chuyện vào trọng tâm đi ông ơi, mấy cái ví dụ này không RELEVANT gì đến vấn đề mình đang gặp cả.', 'Liên quan, phù hợp', 'beginner', 845),
  ('v078', 'significant', 'Tìm được một con mentor tốt sẽ tạo ra thay đổi SIGNIFICANT cho con đường sự nghiệp của ông.', 'Quan trọng, đáng kể', 'beginner', 850),
  ('v079', 'tolerate', 'Tôi không thể TOLERATE nổi cái thói lười biếng mà còn hay đổ lỗi của ông đồng nghiệp cùng team.', 'Tha thứ, chịu đựng', 'beginner', 855),
  ('v080', 'utilize', 'Phải biết cách UTILIZE tối đa sức mạnh của AI để làm việc nhanh hơn, chứ đừng để nó thay thế mình.', 'Sử dụng, tận dụng', 'beginner', 860)
on conflict (id) do update set word = excluded.word, scenario = excluded.scenario,
  translation_hint = excluded.translation_hint, level = excluded.level, elo = excluded.elo;

insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v081', 'valid', 'Cái argument của ông nghe cũng VALID đấy, nhưng áp dụng vào thực tế thì chắc chắn là tạch.', 'Hợp lệ, có cơ sở', 'beginner', 840),
  ('v082', 'willing', 'Tôi WILLING làm thêm giờ nếu công ty trả lương OT sòng phẳng, còn không thì cứ 5h là ''phắn''.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v083', 'abstract', 'Mấy cái định nghĩa về Clean Architecture này nghe ABSTRACT quá, cho tôi ví dụ code thực tế đi.', 'Trừu tượng', 'beginner', 870),
  ('v084', 'benefit', 'Làm ở công ty lớn thì BENEFIT tốt thiệt, nhưng bù lại là quy trình rườm rà phát mệt.', 'Lợi ích, phúc lợi', 'beginner', 825),
  ('v085', 'confident', 'Lúc phỏng vấn thì CONFIDENT lắm, vô làm thật mới biết mình còn non và xanh như trái chuối.', 'Tự tin', 'beginner', 835),
  ('v086', 'diverse', 'Bộ sưu tập cốc cà phê của tôi DIVERSE hơn cả kinh nghiệm sống.', 'Đa dạng', 'beginner', 865),
  ('v087', 'evident', 'EVIDENT là tôi không ngủ đủ giấc: mắt tôi trông như panda mỗi sáng.', 'Rõ ràng, hiển nhiên', 'beginner', 855),
  ('v088', 'focus', 'FOCUS của tôi kéo dài đúng bằng thời gian YouTube ad trước khi skip được.', 'Tập trung', 'beginner', 820),
  ('v089', 'generate', 'Dùng ChatGPT để GENERATE đống dữ liệu mẫu này cho nhanh, chứ ngồi gõ tay chắc đến mùa quýt.', 'Tạo ra', 'beginner', 845),
  ('v090', 'highlight', 'HIGHLIGHT của buổi tiệc tối qua là lúc sếp say rượu rồi bắt đầu đi múa cột.', 'Điểm nhấn, nổi bật', 'beginner', 830),
  ('v091', 'advocating', 'Dù sếp muốn OT không lương, tôi vẫn luôn ADVOCATING cho việc cân bằng cuộc sống, làm xong là về.', 'Ủng hộ, vận động cho', 'intermediate', 960),
  ('v092', 'ambivalent', 'Cảm giác AMBIVALENT vãi: muốn nghỉ việc để tự do nhưng lại sợ không có tiền đóng tiền nhà.', 'Mâu thuẫn, vừa thích vừa ghét', 'intermediate', 980),
  ('v093', 'analogous', 'Việc giải thích code cho sếp không biết kỹ thuật nó ANALOGOUS với việc dạy cá leo cây vậy.', 'Tương tự, giống như', 'intermediate', 1050),
  ('v094', 'articulate', 'Hắn ta ARTICULATE cái plan nghe hay vãi chưởng, dù thực tế là team chưa làm được cái gì cả.', 'Diễn đạt lưu loát', 'intermediate', 1000),
  ('v095', 'assertive', 'Đi phỏng vấn là phải ASSERTIVE lên, mình biết cái gì thì nói chắc cái đó, đừng có ''em nghĩ là''.', 'Quyết đoán, tự tin khẳng định', 'intermediate', 970),
  ('v096', 'biased', 'Đừng có BIASED cho cái framework ông thích mà chê mấy cái khác, cái nào cũng có cái dở thôi.', 'Thiên vị, có thành kiến', 'intermediate', 960),
  ('v097', 'bureaucratic', 'Cái quy trình hoàn tiền ở đây BUREAUCRATIC vãi, bắt ký 7749 cái giấy tờ chỉ để nhận lại 200k.', 'Quan liêu, nhiều thủ tục', 'intermediate', 1080),
  ('v098', 'catalyst', 'Việc bị người yêu cũ cắm sừng chính là CATALYST giúp tôi quyết tâm học code để đổi đời.', 'Chất xúc tác, nhân tố kích thích', 'intermediate', 1020),
  ('v099', 'chronic', 'Cái bệnh trì hoãn của tôi nó thành CHRONIC rồi, cứ phải sát nút mới bắt đầu vắt chân lên cổ.', 'Mãn tính, kinh niên', 'intermediate', 975),
  ('v100', 'comprehensive', 'Tôi cần một cái document COMPREHENSIVE hơn, chứ viết sơ sài thế này bố ai mà hiểu code kiểu gì.', 'Toàn diện, bao quát', 'intermediate', 990),
  ('v101', 'contentious', 'Việc có nên dùng Tailwind hay không là một chủ đề CONTENTIOUS trong giới frontend hiện nay.', 'Gây tranh cãi', 'intermediate', 1060),
  ('v102', 'counterproductive', 'Thức đêm để làm việc nhưng hôm sau ngủ bù cả ngày thì đúng là COUNTERPRODUCTIVE thật sự.', 'Phản tác dụng', 'intermediate', 1100),
  ('v103', 'credible', 'Cái website này nhìn phèn quá, nhìn chẳng CREDIBLE tí nào, ai mà dám nhập thẻ credit vào đây.', 'Đáng tin', 'intermediate', 980),
  ('v104', 'cumulative', 'Hệ quả CUMULATIVE của việc mỗi ngày học 5 từ vựng là sau một năm ông sẽ khác bọt hẳn.', 'Tích lũy, dồn lại', 'intermediate', 1040),
  ('v105', 'cynical', 'Làm nghề này lâu năm khiến tôi trở nên CYNICAL, ai hứa hẹn gì tôi cũng thấy nghi nghi.', 'Hoài nghi, yếm thế', 'intermediate', 965),
  ('v106', 'decisive', 'Làm leader là phải DECISIVE, chứ cứ phân vân mãi thì team biết đường nào mà lần.', 'Quyết đoán', 'intermediate', 970),
  ('v107', 'detrimental', 'Việc ngồi sai tư thế cả ngày rất DETRIMENTAL cho cái cột sống của anh em dev mình.', 'Có hại, bất lợi', 'intermediate', 1030),
  ('v108', 'dynamic', 'Thấy JD ghi ''môi trường DYNAMIC'' là hiểu chuẩn bị tinh thần task bay tới tấp, thay đổi xoành xoạch nhé.', 'Năng động, thay đổi liên tục', 'intermediate', 955),
  ('v109', 'elaborate', 'Ông có thể ELABORATE thêm về cái tính năng này không? Nghe còn mơ hồ quá.', 'Giải thích chi tiết', 'intermediate', 990),
  ('v110', 'empirical', 'Đừng có nói suông, đưa bằng chứng EMPIRICAL ra đây xem tốc độ load app nó tăng được bao nhiêu?', 'Dựa trên thực tế, thực nghiệm', 'intermediate', 1070),
  ('v111', 'explicit', 'Tôi đã dặn EXPLICIT là không được sửa cái file này rồi mà ông vẫn cứ táy máy tay chân nhỉ?', 'Rõ ràng, dứt khoát', 'intermediate', 1000),
  ('v112', 'formidable', 'Đối thủ lần này FORMIDABLE vãi, tech stack của tụi nó toàn thứ dữ, mình phải cẩn thận.', 'Đáng gờm', 'intermediate', 1050),
  ('v113', 'fragmented', 'Hệ sinh thái của Android hơi bị FRAGMENTED, test app trên đống máy này mệt xỉu.', 'Phân mảnh, rời rạc', 'intermediate', 1020),
  ('v114', 'fundamental', 'Mấy cái kiến thức FUNDAMENTAL về JavaScript mà không vững thì học framework chỉ có nát.', 'Cơ bản, thiết yếu', 'intermediate', 960),
  ('v115', 'hypothetical', 'Đây chỉ là tình huống HYPOTHETICAL thôi, nhưng nếu bị hack hết database thì ông tính làm gì?', 'Giả định, giả thuyết', 'intermediate', 1080),
  ('v116', 'implicit', 'Dù sếp không nói ra, nhưng sự im lặng đó mang một thông điệp IMPLICIT là ''lo mà làm đi''.', 'Ngầm định, ẩn ý', 'intermediate', 1040),
  ('v117', 'indispensable', 'Cái thư viện này INDISPENSABLE cho project luôn rồi, gỡ ra cái là app tạch ngay.', 'Không thể thiếu', 'intermediate', 1090),
  ('v118', 'integrate', 'Phải INTEGRATE thêm cái cổng thanh toán này vào app ngay trong tuần tới cho khách.', 'Tích hợp', 'intermediate', 970),
  ('v119', 'intuitive', 'Thiết kế UI phải làm sao cho nó INTUITIVE vào, để người dùng nhìn cái biết bấm đâu luôn.', 'Trực quan, dễ hiểu', 'intermediate', 1010),
  ('v120', 'leverage', 'Cố gắng LEVERAGE đống code cũ đi, đừng có lúc nào cũng đòi viết lại từ đầu cho mệt.', 'Tận dụng lợi thế', 'intermediate', 1000)
on conflict (id) do update set word = excluded.word, scenario = excluded.scenario,
  translation_hint = excluded.translation_hint, level = excluded.level, elo = excluded.elo;

insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v121', 'modicum', 'Chỉ cần sếp có một MODICUM thấu hiểu cho anh em thôi là không khí văn phòng đã đỡ ngộp thở hơn rồi.', 'Một chút, lượng nhỏ tối thiểu', 'intermediate', 1030),
  ('v122', 'momentum', 'Đang có MOMENTUM code ngon lành thì thằng đồng nghiệp sang rủ đi hút thuốc làm đứt mạch luôn.', 'Đà tiến, sức đẩy', 'intermediate', 990),
  ('v123', 'monotonous', 'Mấy cái task MONOTONOUS như copy-paste data này làm tôi thấy mình giống robot hơn là kỹ sư.', 'Đơn điệu, tẻ nhạt', 'intermediate', 975),
  ('v124', 'navigate', 'Việc NAVIGATE trong đống legacy code không có document giống như đi lạc trong rừng rậm vậy.', 'Điều hướng, tìm cách vượt qua', 'intermediate', 960),
  ('v125', 'objective', 'Nói một cách OBJECTIVE thì cái tính năng này chẳng giúp ích gì cho người dùng, chỉ tổ tốn tài nguyên.', 'Khách quan, mục tiêu', 'intermediate', 950),
  ('v126', 'overwhelming', 'Nhìn cái backlog còn 50 task mà deadline chỉ còn 2 ngày, cảm giác thật sự OVERWHELMING.', 'Choáng ngợp, quá tải', 'intermediate', 980),
  ('v127', 'paradox', 'Đúng là một cái PARADOX: Code càng phức tạp thì càng dễ lỗi, mà muốn fix lỗi lại phải thêm code phức tạp hơn.', 'Nghịch lý', 'intermediate', 1050),
  ('v128', 'perceive', 'Khách hàng PERCEIVE cái app mình là cao cấp chỉ vì mình đổi cái font chữ nhìn nó ''sang'' hơn.', 'Nhận thức, cảm nhận', 'intermediate', 1010),
  ('v129', 'perpetual', 'Tôi luôn ở trong trạng thái PERPETUAL mệt mỏi, ngủ bao nhiêu cũng thấy không đủ.', 'Liên tục, vĩnh cửu', 'intermediate', 1060),
  ('v130', 'prevalent', 'Cái văn hóa ''làm màu'' đang ngày càng PREVALENT trong mấy cái startup bây giờ.', 'Phổ biến, thịnh hành', 'intermediate', 1020),
  ('v131', 'proactive', 'Thay vì đợi sếp nhắc, ông nên PROACTIVE cập nhật tình hình dự án đi cho đỡ bị ăn chửi.', 'Chủ động', 'intermediate', 975),
  ('v132', 'profound', 'Những chia sẻ của anh ấy về nghề nghiệp mang lại cho tôi một sự thay đổi PROFOUND trong tư duy.', 'Sâu sắc, thâm thúy', 'intermediate', 1040),
  ('v133', 'rational', 'Đừng có cáu gắt, hãy đưa ra một cái giải trình RATIONAL xem tại sao dự án lại bị delay?', 'Hợp lý, dựa trên lý trí', 'intermediate', 965),
  ('v134', 'skeptical', 'Tôi hơi SKEPTICAL về mấy cái lời hứa ''lương tháng 13, 14'' của mấy công ty này, nghe ảo lắm.', 'Hoài nghi, ngờ vực', 'intermediate', 990),
  ('v135', 'spontaneous', 'Một chuyến đi du lịch SPONTANEOUS cuối tuần này có vẻ là ý hay để xả stress đấy.', 'Ngẫu hứng, bột phát', 'intermediate', 1000),
  ('v136', 'subjective', 'Cái đẹp là SUBJECTIVE, ông thấy cái UI này đẹp nhưng khách hàng thấy nó ''nhức mắt'' thì vẫn phải sửa.', 'Chủ quan', 'intermediate', 975),
  ('v137', 'sustainable', 'Làm việc 14 tiếng một ngày không phải là cách làm SUSTAINABLE đâu, trụ được 1 tháng là ông cháy sạch năng lượng.', 'Bền vững', 'intermediate', 955),
  ('v138', 'transparent', 'Công ty cần TRANSPARENT hơn trong việc xét duyệt tăng lương, chứ cứ mập mờ thế này anh em nản.', 'Minh bạch', 'intermediate', 970),
  ('v139', 'trivial', 'Đừng có tốn thời gian cãi nhau về mấy cái vấn đề TRIVIAL như dùng dấu nháy đơn hay nháy đôi nữa.', 'Tầm thường, vụn vặt', 'intermediate', 960),
  ('v140', 'unprecedented', 'Đợt sụt giảm thị trường crypto vừa rồi là một sự kiện UNPRECEDENTED, không ai lường trước nổi.', 'Chưa từng có tiền lệ', 'intermediate', 1070),
  ('v141', 'vulnerable', 'Cái hệ thống này đang rất VULNERABLE trước các đợt tấn công mạng vì chưa update bản vá.', 'Dễ bị tổn thương', 'intermediate', 1010),
  ('v142', 'warranted', 'Sự lo lắng của khách hàng là hoàn toàn WARRANTED khi app cứ crash liên tục thế này.', 'Có cơ sở, được cho phép', 'intermediate', 1080),
  ('v143', 'acrimonious', 'Buổi họp kết thúc bằng một cuộc tranh cãi ACRIMONIOUS giữa bên dev và bên design.', 'Cay nghiệt, đầy ác ý', 'advanced', 1150),
  ('v144', 'admonish', 'Sếp ADMONISH tôi vì cái tội dám ''commit'' code thẳng lên branch main mà không thèm qua review.', 'Cảnh cáo, khiển trách nhẹ', 'advanced', 1200),
  ('v145', 'affluent', 'Nhìn nhà cửa xe cộ là biết gia đình hắn ta thuộc hàng AFFLUENT rồi, đi làm chắc chỉ để trải nghiệm.', 'Giàu có, thịnh vượng', 'advanced', 1120),
  ('v146', 'alleviate', 'Có thêm một bạn intern hỗ trợ sẽ giúp ALLEVIATE được phần nào khối lượng công việc cho tôi.', 'Giảm nhẹ, làm vơi bớt', 'advanced', 1140),
  ('v147', 'altruistic', 'Ông đừng có tỏ ra ALTRUISTIC, tôi biết ông giúp tôi là để sau này nhờ tôi gánh task hộ chứ gì.', 'Vị tha, không vụ lợi', 'advanced', 1180),
  ('v148', 'aberrant', 'Cái hành vi ABERRANT của hệ thống lúc 12h đêm làm tôi phải thức trắng để tìm nguyên nhân.', 'Bất thường, lệch lạc', 'advanced', 1130),
  ('v149', 'anachronistic', 'Cái tư duy quản lý nhân viên theo kiểu chấm công từng phút thật sự là ANACHRONISTIC trong thời đại WFH này.', 'Lỗi thời, sai thời điểm', 'advanced', 1280),
  ('v150', 'anecdotal', 'Mấy cái tin đồn công ty sắp phá sản chỉ là ANECDOTAL thôi, đừng có nghe rồi hoảng loạn.', 'Dựa trên lời kể, không chính thức', 'advanced', 1160),
  ('v151', 'anomaly', 'Cái bug này đúng là một ANOMALY, test cả trăm lần không sao mà cứ hễ demo cho khách là nó hiện ra.', 'Sự bất thường, dị thường', 'advanced', 1170),
  ('v152', 'antiquated', 'Dùng mấy cái tool ANTIQUATED này để quản lý dự án thì bảo sao năng suất không thấp cho được.', 'Cổ lỗ sĩ, cũ kỹ', 'advanced', 1220),
  ('v153', 'apprehensive', 'Tôi thấy hơi APPREHENSIVE về đợt update hệ thống tối nay, linh tính mách bảo là có gì đó không ổn.', 'E sợ, lo lắng về điều gì đó sắp xảy ra', 'advanced', 1150),
  ('v154', 'arduous', 'Quá trình refactor lại toàn bộ đống code rác này là một hành trình ARDUOUS và đầy nước mắt.', 'Gian nan, cực nhọc', 'advanced', 1200),
  ('v155', 'austere', 'Lối sống AUSTERE của ông ấy: chỉ ăn cơm hộp và code 16 tiếng mỗi ngày để tiết kiệm tiền mua nhà.', 'Khắc khổ, giản dị quá mức', 'advanced', 1240),
  ('v156', 'banal', 'Mấy cái bài post ''Cố gắng lên bạn ơi'' trên LinkedIn nghe BANAL vãi, sáo rỗng chẳng giúp ích gì.', 'Tầm thường, vô vị, sáo rỗng', 'advanced', 1180),
  ('v157', 'benevolent', 'Anh lead này BENEVOLENT lắm, thấy anh em mệt là tự bỏ tiền túi ra order trà sữa về bồi bổ ngay.', 'Nhân từ, rộng lượng', 'advanced', 1160),
  ('v158', 'callous', 'Cái cách công ty sa thải nhân viên thâm niên đúng là CALLOUS, không một lời thông báo trước.', 'Vô tâm, nhẫn tâm', 'advanced', 1190),
  ('v159', 'capitulate', 'Sau 2 tiếng tranh luận gay gắt, tôi đành phải CAPITULATE và làm theo cái yêu cầu vô lý của khách hàng.', 'Đầu hàng, chịu khuất phục', 'advanced', 1250),
  ('v160', 'circumvent', 'Thằng đó luôn tìm cách CIRCUMVENT mấy cái quy trình an mật của công ty để cài phần mềm lậu.', 'Dùng mưu mẹo để lách luật', 'advanced', 1230)
on conflict (id) do update set word = excluded.word, scenario = excluded.scenario,
  translation_hint = excluded.translation_hint, level = excluded.level, elo = excluded.elo;

insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v161', 'clandestine', 'Mấy ông nội đang có một cuộc họp CLANDESTINE trong phòng kín, chắc lại sắp có biến gì rồi.', 'Bí mật, lén lút', 'advanced', 1270),
  ('v162', 'coerce', 'Đừng có dùng chức quyền để COERCE nhân viên làm thêm giờ mà không trả lương, kỳ lắm.', 'Ép buộc, cưỡng bức', 'advanced', 1210),
  ('v163', 'complacent', 'Đừng có COMPLACENT với những gì mình đang biết, công nghệ nó thay đổi nhanh lắm, không học là bị đào thải ngay.', 'Tự mãn, hài lòng với bản thân', 'advanced', 1170),
  ('v164', 'concede', 'Tôi buộc phải CONCEDE là giải pháp của ông tối ưu hơn của tôi, mặc dù tôi không thích ông tí nào.', 'Thừa nhận (thường là miễn cưỡng)', 'advanced', 1150),
  ('v165', 'condescending', 'Cái giọng CONDESCENDING của hắn khi nói chuyện với intern làm ai nhìn vào cũng thấy ngứa mắt.', 'Ra vẻ bề trên, khinh khỉnh', 'advanced', 1200),
  ('v166', 'convoluted', 'Cái logic xử lý của cái module này CONVOLUTED quá, đọc muốn nổ cả não mà chưa hiểu gì.', 'Phức tạp, rắc rối', 'advanced', 1220),
  ('v167', 'credulous', 'Sao ông CREDULOUS thế? Nó bảo ''việc nhẹ lương cao'' mà ông cũng tin cho được à?', 'Cả tin, dễ tin người', 'advanced', 1180),
  ('v168', 'curtail', 'Công ty đang tìm cách CURTAIL mọi khoản chi phí không cần thiết sau một năm làm ăn thua lỗ.', 'Cắt bớt, rút ngắn', 'advanced', 1190),
  ('v169', 'cynicism', 'Sự CYNICISM của ông ấy đối với các startup mới là do ông ấy đã từng bị lừa trắng tay 3 lần.', 'Thái độ hoài nghi, yếm thế', 'advanced', 1160),
  ('v170', 'debilitating', 'Cái bệnh đau lưng DEBILITATING này làm tôi không thể tập trung ngồi code quá 15 phút.', 'Làm suy yếu, làm kiệt sức', 'advanced', 1240),
  ('v171', 'delineate', 'Dự án này cần DELINEATE rõ ràng trách nhiệm của từng người, chứ không là cứ đùn đẩy nhau suốt.', 'Vạch ra, mô tả chi tiết', 'advanced', 1260),
  ('v172', 'discrepancy', 'Có một sự DISCREPANCY cực lớn giữa số tiền ghi trên hóa đơn và số tiền thực tế nhận được.', 'Sự khác nhau, không thống nhất', 'advanced', 1200),
  ('v173', 'dismissive', 'Ông đừng có thái độ DISMISSIVE với ý kiến của người khác như vậy, lỡ họ nói đúng thì sao?', 'Gạt bỏ, coi thường', 'advanced', 1170),
  ('v174', 'disparate', 'Phải kết hợp đống dữ liệu DISPARATE này thành một cái report hoàn chỉnh đúng là một cực hình.', 'Khác hẳn nhau, tạp nham', 'advanced', 1210),
  ('v175', 'draconian', 'Chính sách phạt tiền khi đi muộn ở đây đúng là DRACONIAN, đi trễ 1 phút phạt 100k.', 'Hà khắc, khắc nghiệt', 'advanced', 1280),
  ('v176', 'duplicitous', 'Cái thằng đó sống DUPLICITOUS lắm, trước mặt thì anh anh em em, sau lưng thì đâm chọt đủ điều.', 'Hai mặt, gian trá', 'advanced', 1300),
  ('v177', 'elusive', 'Cái bug này ELUSIVE thật sự, cứ tưởng fix được rồi mà lúc sau nó lại hiện ra ở chỗ khác.', 'Khó nắm bắt, hay lảng tránh', 'advanced', 1190),
  ('v178', 'emulate', 'Tôi luôn cố gắng EMULATE cái cách mà anh lead xử lý vấn đề, cực kỳ bình tĩnh và hiệu quả.', 'Noi gương, học tập theo', 'advanced', 1160),
  ('v179', 'equivocate', 'Đừng có EQUIVOCATE nữa, trả lời thẳng vào vấn đề đi: Dự án này bao giờ thì xong?', 'Nói mập mờ, lập lờ để lừa dối', 'advanced', 1290),
  ('v180', 'exorbitant', 'Cái giá cho một cốc cà phê ở khu vực này đúng là EXORBITANT, bằng mẹ nó tiền ăn cả ngày của tôi.', 'Quá mức, cắt cổ (về giá cả)', 'advanced', 1220),
  ('v181', 'expedient', 'Thôi cứ dùng giải pháp EXPEDIENT này đi, fix tạm cho app chạy cái đã rồi mai tính tiếp, deadline tới mông rồi.', 'Tiện lợi nhất thời, thực dụng', 'advanced', 1230),
  ('v182', 'extraneous', 'Ông xóa bớt mấy cái log EXTRANEOUS này đi, nhìn rối cả mắt mà chẳng giúp ích gì cho việc debug cả.', 'Không liên quan, ngoài lề', 'advanced', 1250),
  ('v183', 'fallacious', 'Cái lập luận ''app chậm là do người dùng mạng yếu'' của ông đúng là FALLACIOUS, do code ông tối ưu kém thì có.', 'Sai lầm, ngụy biện', 'advanced', 1270),
  ('v184', 'fastidious', 'Lão khách hàng này FASTIDIOUS vãi, lệch 1 pixel thôi lão cũng bắt chỉnh lại bằng được mới chịu trả tiền.', 'Khó tính, cầu kỳ thái quá', 'advanced', 1240),
  ('v185', 'fervent', 'Hắn ta là một người FERVENT tin vào tiền ảo, lúc nào cũng rủ rê anh em đầu tư để ''đổi đời''.', 'Nồng nhiệt, tha thiết', 'advanced', 1180),
  ('v186', 'flagrant', 'Việc ông copy nguyên si code của project khác rồi bảo mình tự viết là một sự vi phạm bản quyền FLAGRANT.', 'Trắng trợn, lộ liễu', 'advanced', 1210),
  ('v187', 'fleeting', 'Cái động lực làm việc của tôi nó FLEETING lắm, hăng hái được 5 phút xong lại nằm lướt TikTok tiếp.', 'Thoáng qua, phù du', 'advanced', 1130),
  ('v188', 'forthright', 'Tôi thích cái cách ông ấy FORTHRIGHT thừa nhận sai lầm trong thiết kế hệ thống, bớt tốn thời gian đổ lỗi.', 'Thẳng thắn, bộc trực', 'advanced', 1160),
  ('v189', 'frugal', 'Lối sống FRUGAL của anh em dev: đi làm mang cơm theo cho tiết kiệm để tiền đấy mua bàn phím cơ.', 'Tiết kiệm, thanh đạm', 'advanced', 1140),
  ('v190', 'futile', 'Mọi nỗ lực giải thích cho bà chị HR hiểu về tech stack đều trở nên FUTILE vì bả chỉ quan tâm đến bằng cấp.', 'Vô ích, không kết quả', 'advanced', 1170),
  ('v191', 'gratuitous', 'Mấy cái hiệu ứng chuyển trang GRATUITOUS này làm app nặng thêm chứ chẳng giúp trải nghiệm tốt hơn tí nào.', 'Vô lý, không cần thiết', 'advanced', 1260),
  ('v192', 'hegemony', 'Sự thống trị của Google trong mảng tìm kiếm là một cái HEGEMONY mà chưa ai có thể lật đổ được.', 'Sự bá quyền, thống trị', 'advanced', 1300),
  ('v193', 'hubris', 'Chính cái HUBRIS khi nghĩ mình là senior ''không bao giờ sai'' đã khiến ông ta làm bay màu sạch database.', 'Sự ngạo mạn quá mức', 'advanced', 1280),
  ('v194', 'hypocritical', 'Thật là HYPOCRITICAL khi sếp bắt anh em đi làm đúng giờ trong khi lão toàn 10h mới có mặt.', 'Đạo đức giả', 'advanced', 1190),
  ('v195', 'idealistic', 'Cái suy nghĩ ''làm vì đam mê không cần lương'' nghe thật IDEALISTIC, nhưng thực tế là tiền nhà không ai đóng hộ.', 'Lý tưởng hóa, xa rời thực tế', 'advanced', 1150),
  ('v196', 'inadvertent', 'Tôi lỡ tay bấm INADVERTENT vào nút delete toàn bộ data, giờ thì chuẩn bị dọn đồ về vườn thôi.', 'Vô ý, không chủ tâm', 'advanced', 1230),
  ('v197', 'incongruent', 'Cái hành động của ông nó hoàn toàn INCONGRUENT với những gì ông hứa trong buổi họp tuần trước.', 'Không phù hợp, mâu thuẫn', 'advanced', 1260),
  ('v198', 'indolent', 'Cái nết INDOLENT này của ông mà không sửa thì chẳng có cái task nào hoàn thành đúng hạn được đâu.', 'Lười biếng, nhác làm', 'advanced', 1200),
  ('v199', 'inexorable', 'Sự tiến bộ của AI là một xu hướng INEXORABLE, thay vì sợ hãi thì mình nên tìm cách sống chung với nó.', 'Không thể lay chuyển/ngăn cản', 'advanced', 1310),
  ('v200', 'insidious', 'Mấy cái nợ kỹ thuật (tech debt) nó INSIDIOUS lắm, ban đầu không thấy gì nhưng sau này gỡ mệt xỉu.', 'Âm thầm nguy hại', 'advanced', 1270)
on conflict (id) do update set word = excluded.word, scenario = excluded.scenario,
  translation_hint = excluded.translation_hint, level = excluded.level, elo = excluded.elo;

insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v201', 'intransigent', 'Lão sếp INTRANSIGENT đến mức không chịu lắng nghe bất kỳ góp ý nào về việc thay đổi quy trình làm việc.', 'Cố chấp, không nhượng bộ', 'advanced', 1290),
  ('v202', 'irrevocable', 'Một khi đã bấm deploy lên production thì quyết định đó coi như là IRREVOCABLE, sướng hay khổ phải chịu.', 'Không thể thu hồi/thay đổi', 'advanced', 1300),
  ('v203', 'lamentable', 'Tình trạng code của project này thật sự là LAMENTABLE, nát đến mức không thể cứu vãn nổi.', 'Đáng buồn, đáng tiếc', 'advanced', 1220),
  ('v204', 'lethargic', 'Sáng nay thức dậy thấy người LETHARGIC quá, chắc do đêm qua thức cày code muộn quá đây mà.', 'Uể oải, lờ đờ', 'advanced', 1180),
  ('v205', 'lucid', 'Lâu lắm mới thấy ông này có một cái giải trình LUCID và dễ hiểu đến như vậy, chắc mới uống cà phê xong.', 'Sáng suốt, rõ ràng', 'advanced', 1140),
  ('v206', 'magnanimous', 'Lead mình rất MAGNANIMOUS, sẵn sàng gánh tội thay cho anh em khi dự án bị chậm tiến độ.', 'Hào hiệp, cao thượng', 'advanced', 1250),
  ('v207', 'malleable', 'Mấy đứa intern mới vào thường rất MALLEABLE, dạy gì nghe nấy, dễ uốn nắn hơn mấy ông senior cứng đầu.', 'Dễ bị tác động, dễ uốn nắn', 'advanced', 1210),
  ('v208', 'mendacious', 'Cái bản báo cáo MENDACIOUS này nhằm che đậy sự thật là dự án đang nát bét, đừng hòng lừa được tôi.', 'Sai sự thật, giả dối', 'advanced', 1320),
  ('v209', 'melancholy', 'Chiều Chủ nhật ngồi nghe nhạc trịnh xong thấy lòng MELANCHOLY vãi, nghĩ đến cảnh mai đi làm mà nản.', 'U sầu, buồn bã', 'advanced', 1160),
  ('v210', 'mollify', 'Tôi phải hứa dắt crush đi ăn lẩu mới có thể MOLLIFY được cơn giận của bả vì tội quên reply tin nhắn.', 'Làm nguôi đi, xoa dịu', 'advanced', 1130),
  ('v211', 'mercurial', 'Cái nết MERCURIAL của lão sếp làm anh em mệt mỏi vãi, sáng vừa khen lấy khen để, chiều đã quay sang chửi như tát nước vào mặt.', 'Thất thường, hay thay đổi', 'advanced', 1110),
  ('v212', 'nefarious', 'Tôi nghi ngờ có âm mưu NEFARIOUS đằng sau việc toàn bộ server bị ''wipe'' sạch data ngay trước ngày bàn giao.', 'Hung ác, bất chính', 'advanced', 1310),
  ('v213', 'nonchalant', 'Server sập mà lão lead vẫn cứ NONCHALANT ngồi húp mì tôm như không có chuyện gì xảy ra, nể thật sự.', 'Thờ ơ, lãnh đạm', 'advanced', 1190),
  ('v214', 'nostalgic', 'Ngồi nhìn đống code cũ hồi mới tập tành làm web mà thấy NOSTALGIC vãi, hồi đó ngu ngơ nhưng mà vui.', 'Hoài niệm', 'advanced', 1130),
  ('v215', 'oblivious', 'Thằng đó OBLIVIOUS đến mức không nhận ra là cả team đang ''cạch mặt'' nó vì cái thói hay báo task.', 'Vô tâm, không nhận thấy', 'advanced', 1160),
  ('v216', 'ominous', 'Cái thông báo ''Meeting khẩn toàn công ty'' lúc 5h chiều thứ Sáu nghe OMINOUS vãi, chắc lại sắp layoff rồi.', 'Điềm xấu, đáng lo ngại', 'advanced', 1180),
  ('v217', 'opaque', 'Cái cơ chế tính bonus của công ty này OPAQUE vãi, chẳng ai biết tại sao người được nhiều người được ít.', 'Mập mờ, không minh bạch', 'advanced', 1200),
  ('v218', 'ostentatious', 'Mấy cái văn phòng startup cứ thích trang trí OSTENTATIOUS cho cố vào, trong khi lương nhân viên thì nợ mấy tháng trời.', 'Phô trương, khoe mẽ', 'advanced', 1300),
  ('v219', 'pedantic', 'Lão Reviewer PEDANTIC vãi, code chạy ngon ơ mà lão cứ bắt sửa từng cái dấu cách với xuống dòng cho đúng chuẩn lão mới chịu.', 'Câu nệ, soi xét tiểu tiết', 'advanced', 1250),
  ('v220', 'perfidious', 'Hành động PERFIDIOUS nhất là rủ anh em cùng nghỉ việc, xong mình thì ở lại nhận chức team lead của những người đã đi.', 'Phản bội, xảo trá', 'advanced', 1330),
  ('v221', 'pertinent', 'Trong buổi họp 3 tiếng, chỉ có đúng một câu hỏi của ông là PERTINENT vào vấn đề, còn lại toàn nói nhảm.', 'Đúng trọng tâm, liên quan trực tiếp', 'advanced', 1150),
  ('v222', 'phlegmatic', 'Bạn thân tôi PHLEGMATIC đến mức nghe tin xấu cũng chỉ ''ừ, vậy à''.', 'Điềm tĩnh, lạnh lùng', 'advanced', 1280),
  ('v223', 'placid', 'Vẻ ngoài PLACID của khách hàng lúc này làm tôi thấy lo hơn, chắc là đang chuẩn bị gom hết lỗi để chửi một thể đây.', 'Điềm tĩnh, lặng lẽ', 'advanced', 1200),
  ('v224', 'polarizing', 'Vấn đề dùng ''Tab'' hay ''Space'' đúng là cực kỳ POLARIZING trong cộng đồng dev, cãi nhau cả chục năm chưa xong.', 'Gây chia rẽ, phân cực', 'advanced', 1170),
  ('v225', 'pompous', 'Mấy ông diễn giả hay dùng giọng POMPOUS để nói về những đạo lý ai cũng biết, nghe mà buồn ngủ.', 'Hợm hĩnh, vênh váo', 'advanced', 1220),
  ('v226', 'punctilious', 'Bà kế toán PUNCTILIOUS vãi, sai một chữ cái trong hóa đơn thôi cũng bắt về viết lại từ đầu.', 'Kỹ lưỡng, câu nệ nghi thức', 'advanced', 1280),
  ('v227', 'precarious', 'Cái hệ thống này đang ở trong tình trạng PRECARIOUS vãi, chỉ cần một con bot ddos nhẹ thôi là sập toàn tập.', 'Bấp bênh, nguy hiểm', 'advanced', 1190),
  ('v228', 'presumptuous', 'Thật là PRESUMPTUOUS khi ông nghĩ rằng mình giỏi hơn cả cái team đã làm project này 3 năm nay.', 'Tự phụ, quá trớn', 'advanced', 1260),
  ('v229', 'pretentious', 'Cái profile LinkedIn của lão trông PRETENTIOUS vãi, ghi toàn chức danh nghe kêu như chuông mà hỏi kiến thức thì rỗng tuếch.', 'Giả tạo, tự cao tự đại', 'advanced', 1230),
  ('v230', 'pugnacious', 'Ông đừng có PUGNACIOUS thế, người ta chỉ góp ý nhẹ thôi mà đã nhảy dựng lên muốn đánh người ta rồi.', 'Hay gây gổ, hiếu chiến', 'advanced', 1260),
  ('v231', 'abnegation', 'Sự ABNEGATION của anh ấy đối với đời sống cá nhân để tập trung cứu dự án làm ai cũng nể, nhưng mà hơi cực đoan.', 'Sự hy sinh, từ bỏ quyền lợi', 'expert', 1380),
  ('v232', 'abstemious', 'Bác sĩ bảo phải ABSTEMIOUS với trà sữa và cà phê nếu không muốn cái dạ dày biểu tình, nhưng khó quá Long ơi.', 'Tiết chế, điều độ (ăn uống)', 'expert', 1420),
  ('v233', 'acerbic', 'Mấy cái nhận xét ACERBIC của ông lead làm intern khóc sưng cả mắt, biết là đúng nhưng mà gắt quá.', 'Chua cay, gay gắt', 'expert', 1390),
  ('v234', 'acumen', 'Cái ACUMEN trong kinh doanh của lão sếp đúng là không đùa được, nhìn đâu cũng thấy ra tiền.', 'Sự nhạy bén, sắc sảo', 'expert', 1400),
  ('v235', 'adumbrate', 'Trong buổi kickoff, sếp chỉ ADUMBRATE sơ qua về tầm nhìn của dự án, còn chi tiết thì... đợi khi nào có rồi tính.', 'Phác thảo, ám chỉ sơ lược', 'expert', 1470),
  ('v236', 'anachronism', 'Thời buổi này mà vẫn dùng jQuery cho project mới thì đúng là một cái ANACHRONISM không thể chấp nhận được.', 'Sự lỗi thời, sai thời đại', 'expert', 1440),
  ('v237', 'anathema', 'Họp hành vô tội vạ là một cái ANATHEMA đối với dân dev mình, chỉ tổ tốn thời gian chứ chẳng giải quyết được gì.', 'Điều cực kỳ ghét bỏ', 'expert', 1460),
  ('v238', 'apocryphal', 'Mấy cái câu chuyện về ''thần đồng code 10 tuổi'' thường là APOCRYPHAL thôi, đừng có tin rồi tự tạo áp lực cho mình.', 'Không xác thực, bị bịa đặt', 'expert', 1450),
  ('v239', 'apotheosis', 'Được làm việc tại Google từng là APOTHEOSIS của sự nghiệp dev, nhưng giờ thì mọi chuyện đã khác nhiều rồi.', 'Đỉnh cao, sự thần thánh hóa', 'expert', 1490),
  ('v240', 'approbation', 'Phải vất vả lắm tôi mới nhận được sự APPROBATION của ông CTO cho cái kiến trúc hệ thống mới này.', 'Sự tán thành, chấp thuận', 'expert', 1430)
on conflict (id) do update set word = excluded.word, scenario = excluded.scenario,
  translation_hint = excluded.translation_hint, level = excluded.level, elo = excluded.elo;

insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v241', 'arcane', 'Mấy cái thuật ngữ ARCANE trong smart contract này làm tôi đọc muốn nổ não, đúng là chỉ có mấy ông thần crypto mới hiểu nổi.', 'Bí ẩn, kỳ bí, khó hiểu', 'expert', 1380),
  ('v242', 'arrant', 'Việc ông bảo code này ''tự chạy'' mà không cần server đúng là một sự ARRANT bốc phét, định lừa trẻ con à?', 'Hoàn toàn, hết sức (nghĩa xấu)', 'expert', 1460),
  ('v243', 'artifice', 'Cái vẻ ngoài ''quan tâm nhân viên'' của công ty thực ra chỉ là ARTIFICE để che đậy việc cắt giảm thưởng thôi.', 'Mưu mẹo, sự đánh tráo giả tạo', 'expert', 1420),
  ('v244', 'ascetic', 'Cuộc sống ASCETIC của ông thần CTO: không dùng smartphone, chỉ xài máy tính bàn và ăn cơm chay để tập trung tối đa.', 'Khổ hạnh, tu hành', 'expert', 1440),
  ('v245', 'assiduous', 'Phải công nhận ông intern này ASSIDUOUS thật, ngồi fix cái bug vặt vãnh mà cũng thức trắng đêm để tìm nguyên nhân.', 'Cần cù, siêng năng', 'expert', 1390),
  ('v246', 'atavistic', 'Cái nỗi sợ ATAVISTIC khi thấy server đỏ lòm lúc nửa đêm là thứ mà dev đời nào cũng phải nếm trải qua.', 'Mang tính bản năng nguyên thủy', 'expert', 1480),
  ('v247', 'attenuate', 'Dùng thêm mấy lớp cache này sẽ giúp ATTENUATE áp lực lên database, chứ không là nó sập sớm thôi.', 'Làm yếu đi, giảm cường độ', 'expert', 1410),
  ('v248', 'august', 'Được đứng phát biểu trước các chuyên gia AUGUST trong ngành làm tôi thấy vừa run vừa tự hào vãi.', 'Uy nghi, đáng kính', 'expert', 1370),
  ('v249', 'avarice', 'Chính cái sự AVARICE của ban lãnh đạo, chỉ muốn thu lợi nhuận ngắn hạn, đã làm nát bét cái định hướng dài hạn của dự án.', 'Lòng tham tiền bạc', 'expert', 1430),
  ('v250', 'bellicose', 'Sếp bữa nay có vẻ BELLICOSE vãi, ai nói gì cũng muốn ''bật'' lại, chắc là mới bị vợ mắng ở nhà rồi.', 'Hiếu chiến, thích gây hấn', 'expert', 1400),
  ('v251', 'byzantine', 'Quy trình xin cấp quyền truy cập server ở cái tập đoàn này BYZANTINE vãi, qua 5 tầng 7 lớp ký duyệt mới xong.', 'Rắc rối, cực kỳ phức tạp', 'expert', 1470),
  ('v252', 'capricious', 'Tính tình CAPRICIOUS của khách hàng làm team xoay như chong chóng, sáng đòi làm cái này chiều lại bảo ''thôi bỏ đi''.', 'Thất thường, hay thay đổi', 'expert', 1390),
  ('v253', 'castigate', 'Lead mình thường xuyên CASTIGATE mấy thanh niên hay viết code ''bẩn'' mà không chịu format lại.', 'Chỉ trích dữ dội', 'expert', 1450),
  ('v254', 'caustic', 'Mấy cái lời nhận xét CAUSTIC trong code review có thể làm một anh dev yếu lòng phải suy nghĩ về việc bỏ nghề.', 'Cay nghiệt, châm chọc', 'expert', 1410),
  ('v255', 'chicanery', 'Lão ta dùng đủ mọi CHICANERY để đẩy hết trách nhiệm sai sót sang cho team khác, đúng là cáo già.', 'Mánh khóe, thủ thuật lừa dối', 'expert', 1480),
  ('v256', 'churlish', 'Hành động không thèm trả lời tin nhắn công việc của khách hàng là cực kỳ CHURLISH, dù ông có giận cỡ nào đi nữa.', 'Thô lỗ, mất lịch sự', 'expert', 1380),
  ('v257', 'circumlocution', 'Bớt dùng CIRCUMLOCUTION lại đi ông nội, nói thẳng ra là dự án này khi nào xong cho tôi nhờ cái.', 'Cách nói vòng vo, dài dòng', 'expert', 1490),
  ('v258', 'clairvoyant', 'Lão lead như có khả năng CLAIRVOYANT vậy, nhìn qua là biết ngay chỗ nào trong code sắp tới sẽ nổ bug.', 'Sáng suốt, có khả năng tiên đoán', 'expert', 1420),
  ('v259', 'cloying', 'Cái giọng nịnh hót CLOYING của thằng đó với sếp làm tôi nghe mà muốn nổi hết da gà, giả trân vãi.', 'Ngọt xớt, giả tạo đến phát ngấy', 'expert', 1360),
  ('v260', 'cogent', 'Bài thuyết trình của ông rất COGENT, thuyết phục hoàn toàn ban giám đốc rót vốn cho dự án này.', 'Vững chắc, có sức thuyết phục', 'expert', 1380),
  ('v261', 'compunction', 'Hắn ta lẳng lặng nghỉ việc ngay giữa lúc dự án đang cháy mà không hề có một chút COMPUNCTION nào, tệ thật sự.', 'Sự hối hận, cắn rứt lương tâm', 'expert', 1430),
  ('v262', 'conflagration', 'Một cái bug nhỏ xíu ở module thanh toán đã gây ra một cuộc CONFLAGRATION khủng khiếp, làm app bay màu cả ngày.', 'Đám cháy lớn, sự xung đột dữ dội', 'expert', 1460),
  ('v263', 'consternation', 'Nỗi CONSTERNATION bao trùm cả phòng họp khi sếp thông báo dự án chính thức bị ''cancel'' sau 1 năm cày cuốc.', 'Sự kinh hoàng, tiệt vọng', 'expert', 1460),
  ('v264', 'craven', 'Thật là CRAVEN khi ông đẩy thằng intern ra chịu trận trước khách hàng để bảo vệ cái ghế của mình.', 'Hèn nhát', 'expert', 1400),
  ('v265', 'contrite', 'Nhìn bộ dạng CONTRITE của thằng đệ sau khi làm mất con server của khách mà tôi cũng không nỡ mắng.', 'Ăn năn, hối lỗi', 'expert', 1370),
  ('v266', 'convivial', 'Buổi tiệc tất niên diễn ra trong không khí CONVIVIAL vãi, bao nhiêu mệt mỏi cả năm coi như tan biến sạch.', 'Vui vẻ, thân thiện', 'expert', 1360),
  ('v267', 'copious', 'Ông ghi chép COPIOUS thế kia mà lúc vào họp vẫn hỏi lại mấy cái vấn đề cơ bản là sao?', 'Dồi dào, phong phú', 'expert', 1370),
  ('v268', 'cupidity', 'Chính cái CUPIDITY muốn giàu nhanh đã khiến bao nhiêu người sập bẫy mấy cái sàn crypto lừa đảo.', 'Lòng tham (đặc biệt là tiền bạc)', 'expert', 1450),
  ('v269', 'dearth', 'Hiện nay đang có một sự DEARTH trầm trọng nhân lực biết làm blockchain chất lượng, hèn gì lương cao vãi.', 'Sự khan hiếm, thiếu thốn', 'expert', 1390),
  ('v270', 'deference', 'Ông ấy luôn đối xử với các bậc tiền bối trong ngành với sự DEFERENCE tuyệt đối, đúng chuẩn người có học thức.', 'Sự tôn trọng, cung kính', 'expert', 1400),
  ('v271', 'deleterious', 'Cái thói quen ngồi code xuyên đêm mà không vận động thật sự có ảnh hưởng DELETERIOUS đến cột sống của ông đấy, lo mà tập gym đi.', 'Gây hại, có tác động xấu', 'expert', 1440),
  ('v272', 'denouement', 'Cái DENOUEMENT của dự án này thật không thể tin nổi: sếp ôm tiền chạy, để lại anh em với đống code rác nợ lương 3 tháng.', 'Kết cục, hạ màn', 'expert', 1460),
  ('v273', 'desultory', 'Ông học tiếng Anh kiểu DESULTORY thế này thì mùa quýt sang năm mới đạt được N2, học hành cho nó ra hệ thống tí đi.', 'Rời rạc, thiếu hệ thống', 'expert', 1470),
  ('v274', 'inveterate', 'Thằng đó là một kẻ INVETERATE nói dối, nó bảo ''fix xong rồi'' nghĩa là nó còn chưa thèm mở code ra xem nữa.', 'Thâm căn cố đế, khó bỏ', 'expert', 1410),
  ('v275', 'lachrymose', 'Mấy cái phim quảng cáo Tết lúc nào cũng dùng kịch bản LACHRYMOSE để lấy nước mắt người xem rồi chèn cái logo vào.', 'Hay khóc, ủy mị, gây xúc động mạnh', 'expert', 1450),
  ('v276', 'lambaste', 'Cộng đồng mạng đang LAMBASTE cái app mới ra của công ty vì lỗi bảo mật sơ đẳng làm lộ thông tin người dùng.', 'Chỉ trích gay gắt', 'expert', 1420),
  ('v277', 'languid', 'Thời tiết Sài Gòn buổi chiều nóng đến mức làm ai cũng thấy LANGUID, chỉ muốn nằm điều hòa chứ code gì tầm này.', 'Uể oải, lờ đờ', 'expert', 1380),
  ('v278', 'loquacious', 'Gặp mấy ông khách hàng LOQUACIOUS mệt lắm, nói chuyện 2 tiếng đồng hồ mà chẳng chốt được cái yêu cầu nào ra hồn.', 'Nói nhiều, huyên thuyên', 'expert', 1390),
  ('v279', 'machiavellian', 'Lão ta dùng những thủ đoạn MACHIAVELLIAN để leo lên cái ghế giám đốc, sẵn sàng đạp đổ mọi đồng nghiệp cũ.', 'Xảo quyệt, mưu mô chính trị', 'expert', 1490),
  ('v280', 'magniloquent', 'Mấy cái diễn ngôn MAGNILOQUENT về ''thay đổi thế giới'' của mấy founder startup nghe thì hay, nhưng thực tế là đang đốt tiền nhà đầu tư.', 'Nói khoác lác, khoa trương', 'expert', 1480)
on conflict (id) do update set word = excluded.word, scenario = excluded.scenario,
  translation_hint = excluded.translation_hint, level = excluded.level, elo = excluded.elo;

insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v281', 'maladroit', 'Cách xử lý khủng hoảng truyền thông của công ty đúng là MALADROIT, càng giải thích thì dân tình càng chửi hăng hơn.', 'Vụng về, thiếu khéo léo', 'expert', 1420),
  ('v282', 'malaise', 'Cảm giác MALAISE khi nhận ra mình đã làm dev 3 năm mà vẫn chưa có gì trong tay, kiến thức thì dở dở ương ương.', 'Sự khó chịu, bất an mơ hồ', 'expert', 1400),
  ('v283', 'meretricious', 'Cái UI này nhìn qua thì MERETRICIOUS đấy, màu mè hoa lá hẹ nhưng trải nghiệm người dùng thì tệ không tả nổi.', 'Hào nhoáng nhưng vô giá trị', 'expert', 1470),
  ('v284', 'mettlesome', 'Phải là một người cực kỳ METTLESOME mới dám bỏ việc lương cao để đi khởi nghiệp trong cái giai đoạn kinh tế khó khăn này.', 'Dũng cảm, đầy nghị lực', 'expert', 1440),
  ('v285', 'misanthropic', 'Làm nghề này lâu xong tôi thấy mình hơi MISANTHROPIC, chỉ thích ở một mình với máy tính hơn là đi xã giao với người thật.', 'Ghét người, lánh đời', 'expert', 1460),
  ('v286', 'mnemonic', 'Dùng mấy cái MNEMONIC kiểu này để nhớ từ vựng cũng hay, nhưng quan trọng vẫn là phải áp dụng vào thực tế mới nhớ lâu được.', 'Thuật ghi nhớ', 'expert', 1380),
  ('v287', 'mordant', 'Cái khiếu hài hước MORDANT của lão lead nhiều khi làm anh em hơi thốn, toàn lôi mấy pha ''bóp'' của team ra để khịa.', 'Châm chọc, cay nghiệt', 'expert', 1430),
  ('v288', 'munificent', 'Công ty cũ của tôi cực kỳ MUNIFICENT trong khoản thiết bị, cứ vào làm là được phát ngay combo Macbook Pro và màn hình 4K.', 'Hào phóng, cực kỳ rộng rãi', 'expert', 1410),
  ('v289', 'nebulous', 'Mấy cái lời hứa hẹn về tương lai dự án của sếp vẫn còn NEBULOUS lắm, chưa thấy một cái roadmap nào rõ ràng cả.', 'Mơ hồ, mù mờ', 'expert', 1390),
  ('v290', 'noisome', 'Cái mùi NOISOME từ đống rác tích tụ lâu ngày ở pantry làm tôi không bao giờ dám bén mảng lại gần đó nữa.', 'Hôi thối, khó chịu kinh khủng', 'expert', 1420),
  ('v291', 'obdurate', 'Dù team đã đưa ra đủ mọi bằng chứng là công nghệ này đã cũ, nhưng lão CTO vẫn OBDURATE bắt dùng cho bằng được.', 'Cứng đầu, ngoan cố', 'expert', 1440),
  ('v292', 'obstreperous', 'Gặp mấy thằng cha OBSTREPEROUS trong buổi họp đúng là cực hình, cứ hở tí là hét toáng lên để át tiếng người khác.', 'Ồn ào bướng bỉnh, khó kiểm soát', 'expert', 1470),
  ('v293', 'obtuse', 'Tôi giải thích đến lần thứ 10 rồi mà ông vẫn chưa hiểu thì đúng là ông OBTUSE thật, hay là đang giả vờ thế?', 'Chậm hiểu, đần độn', 'expert', 1380),
  ('v294', 'officious', 'Mấy bà hàng xóm OFFICIOUS vãi, chuyện gì trong nhà tôi bả cũng biết còn rõ hơn cả tôi nữa.', 'Hay lanh chanh, thích can thiệp chuyện người khác', 'expert', 1410),
  ('v295', 'oleaginous', 'Cái nụ cười OLEAGINOUS của lão khách hàng làm tôi thấy nổi hết cả da gà, biết ngay là sắp có yêu cầu oái oăm gì rồi.', 'Nịnh bợ, bóng bẩy (nghĩa bóng)', 'expert', 1490),
  ('v296', 'onerous', 'Việc một mình phải gánh trách nhiệm bảo trì hệ thống cho cả công ty là một công việc cực kỳ ONEROUS.', 'Nặng nề, khó nhọc', 'expert', 1370),
  ('v297', 'opprobrium', 'Ông ta phải đối mặt với sự OPPROBRIUM từ cộng đồng dev sau khi bị phát hiện ăn cắp mã nguồn của đồng nghiệp.', 'Sự chỉ trích dữ dội, vết nhục', 'expert', 1460),
  ('v298', 'parsimonious', 'Công ty này PARSIMONIOUS đến mức cắt luôn cả tiền trà nước, bánh kẹo cho nhân viên vào buổi xế.', 'Bủn xỉn, cực kỳ keo kiệt', 'expert', 1430),
  ('v299', 'pejorative', 'Đừng dùng từ ''thợ code'' như một danh từ PEJORATIVE, mỗi nghề đều có cái giá trị riêng của nó cả.', 'Mang nghĩa xấu, có tính miệt thị', 'expert', 1420),
  ('v300', 'penurious', 'Trong cái tình cảnh PENURIOUS hiện tại, việc chi 200k cho một bữa ăn đối với tôi là một sự xa xỉ tột độ.', 'Nghèo túng, thiếu thốn tột cùng', 'expert', 1450),
  ('v301', 'perspective', 'Thay vì ngồi cãi nhau, hãy thử đổi PERSPECTIVE xem, bồ ông cũng chỉ muốn tốt cho ông nên mới càm ràm thôi.', 'Góc nhìn, quan điểm', 'intermediate', 920),
  ('v302', 'ambitious', 'Cái plan ''làm chủ tiếng Nhật sau 3 tháng'' nghe AMBITIOUS đấy, nhưng thực tế là ông vẫn đang kẹt ở bảng chữ cái thôi.', 'Tham vọng', 'beginner', 850),
  ('v303', 'collaborate', 'Muốn làm một cái party ra trò thì cả nhóm phải biết COLLABORATE, chứ ai cũng làm theo ý mình thì nát.', 'Hợp tác, cộng tác', 'beginner', 880),
  ('v304', 'adaptable', 'Cuộc sống ở thành phố lớn dạy mình phải cực kỳ ADAPTABLE, sáng nắng chiều mưa kẹt xe liên miên vẫn phải cười tươi.', 'Dễ thích nghi', 'intermediate', 940),
  ('v305', 'consistent', 'Học từ vựng quan trọng nhất là phải CONSISTENT, mỗi ngày 5 từ thôi còn hơn là một ngày 50 từ rồi bỏ cả tháng.', 'Nhất quán, kiên trì', 'intermediate', 910),
  ('v306', 'obtain', 'Phải vất vả lắm tôi mới OBTAIN được cái visa du lịch, làm đống giấy tờ muốn tiền đình luôn.', 'Đạt được, giành được', 'intermediate', 960),
  ('v307', 'specific', 'Nói SPECIFIC vào, ông muốn quà gì cho sinh nhật? Cứ ''gì cũng được'' là tôi tặng cho cái nịt đấy.', 'Cụ thể, rõ ràng', 'beginner', 830),
  ('v308', 'valuable', 'Mấy cái kinh nghiệm ''bị lừa'' hồi sinh viên thực ra là những bài học VALUABLE nhất cho sau này đấy.', 'Quý giá, có giá trị', 'beginner', 840),
  ('v309', 'estimate', 'Ông thử ESTIMATE xem đi từ đây ra sân bay mất bao lâu, kẹt xe tầm này là mệt lắm đấy.', 'Ước tính', 'beginner', 880),
  ('v310', 'typical', 'Hứa thật nhiều xong lại quên, đúng là phong cách TYPICAL của thằng bạn thân tôi.', 'Điển hình, đặc trưng', 'beginner', 820),
  ('v311', 'versatile', 'Cái áo này VERSATILE vãi, mặc đi làm cũng lịch sự mà mặc đi quẩy cũng hết bài.', 'Linh hoạt, đa năng', 'intermediate', 1050),
  ('v312', 'sufficient', 'Ăn một bát phở là SUFFICIENT năng lượng cho cả buổi sáng rồi, không cần ăn thêm gì đâu.', 'Đầy đủ, đủ dùng', 'intermediate', 940),
  ('v313', 'priority', 'Ngủ đủ 8 tiếng phải là PRIORITY hàng đầu nếu ông không muốn trông như panda mỗi sáng.', 'Sự ưu tiên', 'beginner', 850),
  ('v314', 'approach', 'Cái APPROACH của ông để tán crush có vẻ hơi sai sai, thử chuyển sang nhắn tin ''Ok.'' xem.', 'Cách tiếp cận, phương pháp', 'intermediate', 920),
  ('v315', 'convince', 'Làm sao để CONVINCE mẹ cho đi phượt với hội bạn bây giờ? Khó hơn giải toán lý lượng tử.', 'Thuyết phục', 'beginner', 870),
  ('v316', 'procedure', 'Cứ làm đúng cái PROCEDURE khi nấu mì tôm: nước sôi, mì vào, gia vị sau. Đừng có sáng tạo quá.', 'Quy trình, thủ tục', 'intermediate', 950),
  ('v317', 'significance', 'Nhiều người không hiểu được cái SIGNIFICANCE của việc đeo khẩu trang cho đến khi bị dính bụi mịn sml.', 'Tầm quan trọng, ý nghĩa', 'intermediate', 1020),
  ('v318', 'reveal', 'Vừa REVEAL cái ảnh selfie lên Story là crush ''unseen'' luôn, đúng là trái đắng.', 'Tiết lộ, hé lộ', 'beginner', 830),
  ('v319', 'challenging', 'Học tiếng Nhật là một việc cực kỳ CHALLENGING, nhưng mà vì ghẹ Nhật tôi sẽ cố hết sức.', 'Đầy thách thức', 'beginner', 890),
  ('v320', 'acquire', 'Phải mất 2 năm đi làm tôi mới ACQUIRE được kỹ năng ''giả vờ bận rộn'' mỗi khi sếp đi ngang qua.', 'Có được, thu nhận được', 'intermediate', 960)
on conflict (id) do update set word = excluded.word, scenario = excluded.scenario,
  translation_hint = excluded.translation_hint, level = excluded.level, elo = excluded.elo;

insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v321', 'beneficial', 'Uống nước cam mỗi sáng cực kỳ BENEFICIAL cho sức khỏe, nhất là mấy ông hay nhậu nhẹt.', 'Có lợi', 'beginner', 850),
  ('v322', 'capable', 'Tôi biết ông CAPABLE mà, mấy cái task hóc búa này chỉ có ông mới giải quyết nổi thôi.', 'Có khả năng, năng lực', 'beginner', 870),
  ('v323', 'contradict', 'Lời nói của sếp luôn CONTRADICT với hành động, miệng bảo ''anh em là nhà'' mà lại bắt OT xuyên lễ.', 'Mâu thuẫn, trái ngược', 'intermediate', 980),
  ('v324', 'distinct', 'Có một sự DISTINCT rõ rệt giữa cơm mẹ nấu và cơm quán, dù cơm quán cũng ngon nhưng thiếu cái ''tâm''.', 'Khác biệt rõ ràng', 'intermediate', 910),
  ('v325', 'eliminate', 'Mục tiêu của tôi năm nay là ELIMINATE toàn bộ đống mỡ bụng này để tự tin đi bơi.', 'Loại bỏ, triệt tiêu', 'intermediate', 930),
  ('v326', 'generalize', 'Đừng có GENERALIZE là tất cả mọi người đều lười, thực ra chỉ có mỗi ông là lười thôi đấy.', 'Khái quát hóa, đánh đồng', 'intermediate', 950),
  ('v327', 'hinder', 'Mấy cái tin nhắn rác đang HINDER sự tập trung của tôi, chắc phải bật chế độ máy bay thôi.', 'Cản trở, kìm hãm', 'intermediate', 970),
  ('v328', 'implement', 'Cái plan này hay đấy, nhưng vấn đề là ai sẽ là người đứng ra IMPLEMENT đây?', 'Triển khai, thực hiện', 'intermediate', 920),
  ('v329', 'inadequate', 'Kỹ năng thả thính của tôi vẫn còn INADEQUATE vãi, tán bả mà bả toàn rep bằng sticker.', 'Thiếu hụt, không thỏa đáng', 'intermediate', 990),
  ('v330', 'maintain', 'Muốn MAINTAIN được cái body 6 múi thì ông phải bớt ăn trà sữa lại, thực tế lên.', 'Duy trì, bảo trì', 'beginner', 860),
  ('v331', 'notable', 'Một thay đổi NOTABLE nhất sau khi ông đi tập gym là... ông ăn nhiều hơn gấp đôi bình thường.', 'Đáng chú ý, nổi bật', 'beginner', 890),
  ('v332', 'optimistic', 'Dù lương chưa về nhưng ông vẫn OPTIMISTIC chốt đơn Shopee, đúng là tấm gương vượt khó.', 'Lạc quan', 'beginner', 840),
  ('v333', 'partial', 'Đây mới chỉ là PARTIAL sự thật thôi, muốn nghe hết drama thì ông phải bao tôi chầu cà phê đã.', 'Một phần, thiên vị', 'beginner', 830),
  ('v334', 'practical', 'Thôi bớt nói lý thuyết đi, đưa ra giải pháp nào PRACTICAL một tí xem, ví dụ như làm sao để có bồ chẳng hạn.', 'Thực tế, thực tiễn', 'beginner', 870),
  ('v335', 'quickly', 'Dọn dẹp bãi chiến trường này QUICKLY đi ông ơi, mẹ sắp về tới đầu ngõ rồi kìa.', 'Nhanh chóng', 'beginner', 800),
  ('v336', 'reaction', 'REACTION của con mèo khi tôi đưa miếng xúc xắc cho nó thật sự là ''vô giá''.', 'Phản ứng', 'beginner', 820),
  ('v337', 'skepticism', 'Tôi nhìn cái quảng cáo ''kem tan mỡ bụng sau 1 đêm'' với một sự SKEPTICISM cực lớn.', 'Sự hoài nghi', 'intermediate', 1040),
  ('v338', 'tendency', 'Bạn thân tôi có TENDENCY nói rất nhiều mỗi khi nó thấy NERVOUS.', 'Xu hướng, khuynh hướng', 'intermediate', 910),
  ('v339', 'unexpected', 'Một cái UNEXPECTED plot twist cuối phim làm tôi đứng hình mất 5 giây, không thể tin nổi.', 'Bất ngờ, không mong đợi', 'beginner', 850),
  ('v340', 'validate', 'Đừng có tự huyễn hoặc bản thân, hãy nhờ ai đó khách quan VALIDATE cái ý tưởng khởi nghiệp của ông đi.', 'Xác nhận, phê chuẩn', 'intermediate', 940),
  ('v341', 'worthwhile', 'Dù mệt nhưng chuyến leo núi này cực kỳ WORTHWHILE khi được ngắm bình minh trên đỉnh mây.', 'Đáng công, xứng đáng', 'intermediate', 900),
  ('v342', 'yield', 'Chế độ ăn kiêng này bắt đầu YIELD những kết quả khả quan sau 1 tháng tôi kiên trì nhịn trà sữa.', 'Mang lại, sản sinh ra, nhượng bộ', 'intermediate', 1020),
  ('v343', 'abandon', 'Đừng có ABANDON cái ước mơ của mình chỉ vì một vài lời chê bai từ mấy đứa chẳng biết gì.', 'Từ bỏ, bỏ rơi', 'beginner', 880),
  ('v344', 'brief', 'Cho tôi một cái BRIEF về những gì đã xảy ra tối qua đi, tôi không nhớ nổi mình đã uống bao nhiêu nữa.', 'Ngắn gọn, tóm tắt', 'beginner', 830),
  ('v345', 'certain', 'Tôi CERTAIN 100% là ông đã lén ăn cái bánh kem của tôi trong tủ lạnh rồi, đừng có chối.', 'Chắc chắn', 'beginner', 810),
  ('v346', 'decline', 'Tôi buộc phải DECLINE lời mời đi nhậu vì tối nay phải về ''nộp bài'' cho vợ rồi.', 'Từ chối, suy giảm', 'intermediate', 940),
  ('v347', 'accommodate', 'Khách sạn này nhỏ quá, không đủ chỗ để ACCOMMODATE cả hội bạn thân của ông đâu.', 'Đáp ứng, cung cấp chỗ ở', 'intermediate', 960),
  ('v348', 'deliberate', 'Tôi nghĩ hắn ta DELIBERATE lờ tin nhắn của ông đấy, chứ làm gì có chuyện ngủ từ 8h tối.', 'Cố ý, thận trọng', 'intermediate', 980),
  ('v349', 'financial', 'Tình hình FINANCIAL của tôi dạo này hơi ''báo động đỏ'' sau khi nạp tiền vào game quá đà.', 'Thuộc về tài chính', 'beginner', 840),
  ('v350', 'generous', 'Hôm nay ông GENEROUS đột xuất vậy, mời cả hội đi ăn lẩu luôn à?', 'Hào phóng, rộng lượng', 'beginner', 835),
  ('v351', 'immediate', 'Tôi cần một câu trả lời IMMEDIATE, chứ cứ ''để mình suy nghĩ'' thì biết bao giờ mới xong.', 'Ngay lập tức', 'beginner', 845),
  ('v352', 'knowledgeable', 'Anh ấy rất KNOWLEDGEABLE về mảng ẩm thực Sài Gòn, hỏi quán nào cũng biết hết.', 'Am hiểu, có kiến thức rộng', 'intermediate', 950),
  ('v353', 'motivate', 'Nhìn vào cái số dư tài khoản là cách tốt nhất để MOTIVATE bản thân dậy đi làm mỗi sáng.', 'Thúc đẩy, tạo động lực', 'beginner', 860),
  ('v354', 'negative', 'Bớt suy nghĩ NEGATIVE lại ông ơi, đời còn dài, gái còn nhiều, lo gì cái chuyện lẻ bóng.', 'Tiêu cực', 'beginner', 810),
  ('v355', 'quality', 'Thà có một vài người bạn QUALITY còn hơn là có cả nghìn bạn trên Facebook mà chẳng ai thèm hỏi thăm.', 'Chất lượng', 'beginner', 805),
  ('v356', 'reasonable', 'Mức giá cho cái áo này là khá REASONABLE, không quá đắt mà mặc lại chất lừ.', 'Hợp lý, phải chăng', 'beginner', 855),
  ('v357', 'ultimate', 'Mục tiêu ULTIMATE của tôi là được nghỉ hưu sớm và đi du lịch khắp thế giới cùng người yêu.', 'Cuối cùng, tối thượng', 'intermediate', 940),
  ('v358', 'vague', 'Lời hứa ''hôm nào cà phê nhé'' là cái thứ VAGUE nhất trần đời, thường là chẳng bao giờ có cái ''hôm nào'' đó.', 'Mơ hồ, mập mờ', 'intermediate', 910),
  ('v359', 'dependable', 'Thằng bạn thân tôi là một người cực kỳ DEPENDABLE, lúc nào hoạn nạn cũng thấy mặt nó đầu tiên.', 'Đáng tin cậy', 'intermediate', 930),
  ('v360', 'effective', 'Uống nước chanh mật ong là cách EFFECTIVE nhất để trị đau họng sau một đêm hát karaoke cháy máy.', 'Hiệu quả', 'beginner', 850)
on conflict (id) do update set word = excluded.word, scenario = excluded.scenario,
  translation_hint = excluded.translation_hint, level = excluded.level, elo = excluded.elo;

insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v361', 'appropriate', 'Đi đám cưới mà mặc quần short áo ba lỗ thì thật sự không APPROPRIATE tí nào đâu ông nội.', 'Phù hợp, thích hợp', 'intermediate', 960),
  ('v362', 'behave', 'Ra mắt nhà bạn gái thì nhớ BEHAVE cho nó đàng hoàng, đừng có hở tí là văng tục như lúc ở với anh em.', 'Cư xử, ăn ở', 'beginner', 820),
  ('v363', 'coincidence', 'Đúng là một cái COINCIDENCE kỳ lạ, vừa mới nhắc đến tên hắn xong là hắn gọi điện tới luôn.', 'Sự trùng hợp ngẫu nhiên', 'intermediate', 980),
  ('v364', 'determined', 'Thấy bồ cũ có người yêu mới, tôi DETERMINED phải giảm cân để cho bả thấy bả đã đánh mất cái gì.', 'Quyết tâm, kiên quyết', 'beginner', 880),
  ('v365', 'encourage', 'Mẹ tôi luôn ENCOURAGE tôi theo đuổi đam mê, miễn là đừng có về nhà xin tiền mẹ là được.', 'Khuyến khích, động viên', 'beginner', 860),
  ('v366', 'familiar', 'Cái quán cà phê này nhìn FAMILIAR quá, hình như đây là nơi mình bị người yêu cũ đá thì phải.', 'Quen thuộc', 'beginner', 810),
  ('v367', 'hinder', 'Mấy cái tin nhắn rác cứ ting ting suốt đang HINDER sự tập trung của tôi, bực vãi.', 'Cản trở, kìm hãm', 'intermediate', 970),
  ('v368', 'imitate', 'Đứa em tôi nó suốt ngày IMITATE cái giọng của tôi để đi lừa bố mẹ lấy tiền ăn vặt, nhìn mà ghét.', 'Bắt chước, nhại lại', 'intermediate', 940),
  ('v369', 'jealous', 'Mỗi lần thấy tôi đi chơi với bạn nữ khác là người yêu tôi lại JEALOUS ra mặt luôn, dù chỉ là bạn thân.', 'Ghen tị, ghen tuông', 'beginner', 830),
  ('v370', 'limit', 'Tửu lượng của tôi có LIMIT thôi, mấy ông đừng có ép tôi uống thêm nữa kẻo tôi ''huệ'' tại chỗ.', 'Giới hạn, hạn mức', 'beginner', 815),
  ('v371', 'notice', 'Tôi vừa mới NOTICE là nãy giờ tôi đang mặc áo trái đi ngoài đường, nhục không để đâu cho hết.', 'Để ý thấy, nhận ra', 'beginner', 810),
  ('v372', 'patient', 'Muốn tán đổ crush thì phải PATIENT, chứ mới nhắn tin 2 ngày đã đòi yêu thì bả chạy mất dép.', 'Kiên nhẫn', 'beginner', 825),
  ('v373', 'quarrel', 'Mới sáng ra đã nghe thấy nhà hàng xóm QUARREL về việc ai là người đi đổ rác, mệt mỏi thật.', 'Cãi vã, tranh chấp', 'intermediate', 930),
  ('v374', 'stubborn', 'Con mèo nhà tôi STUBBORN lắm, bảo nó xuống khỏi bàn mà nó cứ lỳ ra đó nhìn mình khinh bỉ.', 'Bướng bỉnh, lỳ lợm', 'beginner', 860),
  ('v375', 'temporary', 'Đừng lo, thất nghiệp chỉ là TEMPORARY thôi, lo mà học thêm skill mới đi rồi việc sẽ tới.', 'Tạm thời', 'beginner', 870),
  ('v376', 'urgent', 'Đang đi vệ sinh mà sếp gọi điện báo có việc URGENT thì đúng là một trải nghiệm đau khổ.', 'Khẩn cấp', 'beginner', 845),
  ('v377', 'willing', 'Tôi luôn WILLING đi nhậu nếu có ai đó bao, còn chia tiền thì để tôi xem lại lịch đã nha.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v378', 'accurate', 'Cái cân này có vẻ không ACCURATE lắm, hôm qua tôi cân 70kg mà nay nó nhảy lên 75kg là sao?', 'Chính xác', 'beginner', 880),
  ('v379', 'believable', 'Ông bảo ông đi làm muộn vì ''cứu người qua đường'' nghe chẳng BELIEVABLE tí nào đâu, bớt bốc phét lại.', 'Có thể tin được', 'beginner', 815),
  ('v380', 'convenient', 'Cái app này CONVENIENT thật sự, đặt một cái là 15 phút sau đồ ăn đã ship tới tận cửa.', 'Tiện lợi', 'beginner', 820),
  ('v381', 'dependable', 'Trong nhóm bạn, lúc nào cũng cần một đứa DEPENDABLE để nó đứng ra lo liệu mọi thứ khi đi du lịch.', 'Đáng tin cậy', 'intermediate', 930),
  ('v382', 'effective', 'Uống nước chanh mật ong là cách EFFECTIVE nhất để trị đau họng sau một đêm hát karaoke cháy máy.', 'Hiệu quả', 'beginner', 850),
  ('v383', 'grateful', 'Tôi rất GRATEFUL vì cuối tháng hết tiền vẫn được thằng bạn thân cho ăn ké mì tôm qua ngày.', 'Biết ơn', 'beginner', 860),
  ('v384', 'honest', 'Nói HONEST nhé, cái váy này mặc vào trông bà như cái bánh chưng vậy, đổi cái khác đi.', 'Thành thật, chân thật', 'beginner', 810),
  ('v385', 'ignore', 'Cách tốt nhất để giữ tâm hồn thanh tịnh là IGNORE mấy cái lời drama, bóc phốt nhảm nhí trên Facebook.', 'Phớt lờ, lờ đi', 'beginner', 820),
  ('v386', 'intention', 'Tôi biết INTENTION của ông là muốn giúp bả, nhưng cách ông làm chỉ khiến bả thấy bị làm phiền thêm thôi.', 'Ý định, mục đích', 'intermediate', 910),
  ('v387', 'manage', 'Cuối tháng mà tài khoản còn 200k thì phải biết MANAGE chi tiêu cực khéo mới sống sót được đến ngày nhận lương.', 'Quản lý, xoay xở', 'beginner', 850),
  ('v388', 'necessary', 'Mua thêm cái sạc dự phòng là cực kỳ NECESSARY cho mấy chuyến đi phượt xa, không là điện thoại hết pin giữa đường là mệt.', 'Cần thiết', 'beginner', 840),
  ('v389', 'optimistic', 'Dù bị crush từ chối nhưng hắn vẫn rất OPTIMISTIC, bảo rằng ''chắc tại bả đang thử thách mình thôi''.', 'Lạc quan', 'beginner', 840),
  ('v390', 'partial', 'Đây mới chỉ là một PARTIAL sự thật thôi, đợi khi nào ông biết hết cả câu chuyện thì ông mới thấy nó sốc cỡ nào.', 'Một phần, thiên vị', 'beginner', 830),
  ('v391', 'significant', 'Việc ông bớt ăn vặt lại sẽ tạo ra thay đổi SIGNIFICANT cho cái bụng mỡ của ông đấy, tin tôi đi.', 'Quan trọng, đáng kể', 'beginner', 850),
  ('v392', 'tolerate', 'Tôi không thể TOLERATE nổi cái thói quen vừa ăn vừa nhai nhóp nhép của ông, nhìn mất lịch sự vãi.', 'Chịu đựng, tha thứ', 'beginner', 855),
  ('v393', 'utilize', 'Ông nên UTILIZE cái đống voucher Shopee đi, để lâu nó hết hạn thì tiếc đứt ruột.', 'Sử dụng, tận dụng', 'beginner', 860),
  ('v394', 'valid', 'Lý do ''xe hỏng'' chỉ VALID khi ông thật sự dắt bộ thôi, chứ tôi thấy ông vừa check-in quán cà phê nhé.', 'Hợp lệ, có cơ sở', 'beginner', 840),
  ('v395', 'wonder', 'Nhiều khi tôi WONDER không biết tại sao crush lại có thể ''seen'' tin nhắn của tôi nhanh đến thế.', 'Tự hỏi, băn khoăn', 'beginner', 810),
  ('v396', 'admit', 'Cuối cùng thì ông cũng chịu ADMIT là mình đã lỡ tay xóa mất cái folder ảnh cưới của tôi rồi hả?', 'Thừa nhận, nhận vào', 'beginner', 865),
  ('v397', 'boring', 'Mấy cái buổi họp kéo dài 3 tiếng đồng hồ mà chẳng chốt được gì thật sự rất BORING.', 'Buồn chán, tẻ nhạt', 'beginner', 800),
  ('v398', 'complain', 'Thôi bớt COMPLAIN về việc kẹt xe đi, ở thành phố này thì đó là ''đặc sản'' rồi, tập sống chung với nó thôi.', 'Than phiền, phàn nàn', 'beginner', 820),
  ('v399', 'doubt', 'Tôi DOUBT là cái shop này bán hàng chính hãng, nhìn cái giá ''rẻ bất ngờ'' thế kia là thấy nghi rồi.', 'Nghi ngờ', 'beginner', 855),
  ('v400', 'eager', 'Bọn trẻ con lúc nào cũng EAGER chờ đến Tết để được nhận lì xì, còn người lớn thì ngược lại.', 'Háo hức, hăm hở', 'intermediate', 920)
on conflict (id) do update set word = excluded.word, scenario = excluded.scenario,
  translation_hint = excluded.translation_hint, level = excluded.level, elo = excluded.elo;

insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v401', 'force', 'Đừng có FORCE mình phải cười khi đang thấy buồn, cứ khóc một tí cho nó nhẹ lòng đi.', 'Ép buộc, lực lượng', 'beginner', 840),
  ('v402', 'gather', 'Cuối tuần anh em mình GATHER lại làm chầu bia rồi chém gió cho đỡ stress đi ông ơi.', 'Tập hợp, thu thập', 'beginner', 830),
  ('v403', 'hardly', 'Dạo này bận quá, tôi HARDLY có thời gian để gọi điện về cho bố mẹ ở quê nữa, tội lỗi thật.', 'Hầu như không', 'beginner', 815),
  ('v404', 'imagine', 'Không thể IMAGINE nổi cuộc sống sẽ ra sao nếu một ngày đẹp trời ông bị mất cái điện thoại.', 'Tưởng tượng', 'beginner', 805),
  ('v405', 'kindness', 'Một chút KINDNESS giữa người với người có thể làm một ngày tồi tệ của ông trở nên tươi sáng hơn đấy.', 'Sự tử tế, lòng tốt', 'beginner', 820),
  ('v406', 'loose', 'Cái quần này dạo này mặc thấy LOOSE quá, chắc là do tôi mới giảm được vài ký sau đợt thất tình.', 'Lỏng lẻo, rộng', 'beginner', 835),
  ('v407', 'mention', 'Đừng có MENTION chuyện người yêu cũ trước mặt bả, bả đang nhạy cảm chuyện đó lắm đấy.', 'Đề cập đến', 'beginner', 840),
  ('v408', 'offer', 'Công ty đó vừa mới OFFER cho tôi một vị trí khá tốt, đang phân vân không biết có nên đổi việc không.', 'Đề nghị, mời chào', 'beginner', 850),
  ('v409', 'particular', 'Tôi không có sở thích gì PARTICULAR cả, cứ cái gì vui thì làm, cái gì ngon thì ăn thôi.', 'Cụ thể, đặc biệt', 'intermediate', 910),
  ('v410', 'qualify', 'Phải cày thêm cái bằng tiếng Anh mới QUALIFY cho cái vị trí quản lý mà sếp đang nhắm cho mình được.', 'Đủ điều kiện, tư cách', 'intermediate', 940),
  ('v411', 'struggle', 'Sáng nào tôi cũng phải STRUGGLE với cái báo thức, tắt đi bật lại 5 lần mới chịu dậy nổi.', 'Vật lộn, đấu tranh', 'beginner', 880),
  ('v412', 'thorough', 'Trước khi dắt xe ra khỏi bãi, nhớ check THOROUGH xem có bị trầy xước chỗ nào không kẻo mất tiền oan.', 'Kỹ lưỡng, thấu đáo', 'intermediate', 960),
  ('v413', 'unique', 'Cái phong cách ăn mặc của ông đúng là UNIQUE thật, ra đường đảm bảo không sợ đụng hàng với ai luôn.', 'Độc nhất, độc đáo', 'beginner', 860),
  ('v414', 'whisper', 'Hai đứa nó cứ WHISPER với nhau trong góc lớp, nhìn là biết đang có ''biến'' gì to lắm rồi.', 'Thì thầm', 'beginner', 830),
  ('v415', 'annoying', 'Mấy cái tin nhắn rác mời chào mua nhà, chứng khoán lúc giữa trưa thật sự ANNOYING vãi chưởng.', 'Làm phiền, khó chịu', 'beginner', 820),
  ('v416', 'believe', 'Tôi không thể BELIEVE nổi là thằng bạn thân mình lại đi tin mấy cái lời ''thả thính'' dạo trên mạng.', 'Tin tưởng', 'beginner', 800),
  ('v417', 'critical', 'Đây là giai đoạn CRITICAL của dự án, sai một li là đi một dặm nên anh em cẩn thận giùm cái.', 'Quan trọng, nguy cấp, phê bình', 'intermediate', 970),
  ('v418', 'delighted', 'Mẹ tôi cực kỳ DELIGHTED khi thấy tôi đem về tặng mẹ một bó hoa vào ngày 8/3, dù mẹ vẫn mắng tôi tốn tiền.', 'Vui mừng, hài lòng', 'beginner', 890),
  ('v419', 'frustrated', 'Cảm giác FRUSTRATED nhất là khi đang chuẩn bị thanh toán thì app ngân hàng bị lỗi bảo trì, đứng hình tại quầy luôn.', 'Bực bội, nản lòng', 'beginner', 870),
  ('v420', 'influence', 'Mấy cái video trên TikTok có INFLUENCE cực lớn đến cách tiêu xài của giới trẻ bây giờ đấy, cẩn thận kẻo ''cháy túi''.', 'Ảnh hưởng, tác động', 'intermediate', 915),
  ('v421', 'judge', 'Đừng có vội JUDGE người khác qua vẻ bề ngoài, nhìn bặm trợn thế thôi chứ ổng hiền khô hà.', 'Đánh giá, phán xét', 'beginner', 830),
  ('v422', 'knowledge', 'KNOWLEDGE là thứ duy nhất mà không ai có thể lấy mất của ông, nên cứ đầu tư vào bản thân đi.', 'Kiến thức, sự hiểu biết', 'beginner', 840),
  ('v423', 'lack', 'Cái món canh này hơi LACK vị chua, cho thêm tí chanh vào là đảm bảo cực phẩm luôn.', 'Thiếu hụt', 'beginner', 810),
  ('v424', 'maintain', 'Muốn MAINTAIN một mối quan hệ lâu dài thì cả hai đều phải biết nhường nhịn nhau một tí.', 'Duy trì, giữ vững', 'beginner', 865),
  ('v425', 'nervous', 'Lần đầu ra mắt nhà vợ mà NERVOUS quá nên tôi trả lời cứ ấp a ấp úng, nhạc phụ đại nhân cười mãi.', 'Lo lắng, hồi hộp', 'beginner', 815),
  ('v426', 'opportunity', 'Cơ hội không đến lần hai đâu, thấy OPPORTUNITY là phải ''vồ'' lấy ngay đừng có chần chừ.', 'Cơ hội', 'beginner', 850),
  ('v427', 'prefer', 'Tôi PREFER đi cà phê vỉa hè hơn là vào mấy quán máy lạnh sang chảnh, thấy nó thoải mái hơn.', 'Thích hơn', 'beginner', 820),
  ('v428', 'quality', 'Mua đồ thì nên chọn QUALITY hơn là quantity, thà mặc một cái áo xịn còn hơn mười cái áo dỏm.', 'Chất lượng, đặc tính', 'beginner', 805),
  ('v429', 'recognize', 'Dạo này ông thay đổi nhiều quá, suýt nữa là tôi không RECOGNIZE ra ông luôn đấy.', 'Nhận ra, công nhận', 'beginner', 875),
  ('v430', 'sensitive', 'Bả đang ở trong giai đoạn SENSITIVE, ông nói năng gì cũng phải uốn lưỡi 7 lần kẻo ăn tát.', 'Nhạy cảm', 'intermediate', 935),
  ('v431', 'trustworthy', 'Phải chọn người nào thật sự TRUSTWORTHY mới dám giao cái ''quỹ đen'' này cho mà giữ hộ.', 'Đáng tin cậy', 'intermediate', 925),
  ('v432', 'urgent', 'Có tin nhắn URGENT từ bồ: ''Anh ơi em đói''. Thế là phải xách xe đi mua đồ ăn ngay không bả dỗi.', 'Khẩn cấp', 'beginner', 845),
  ('v433', 'valuable', 'Đừng tốn thời gian VALUABLE của mình để đi giải thích với những người không muốn hiểu.', 'Quý giá', 'beginner', 855),
  ('v434', 'particular', 'Tôi không có sở thích gì PARTICULAR cả, cứ cái gì vui thì làm, cái gì ngon thì ăn thôi.', 'Cụ thể, đặc biệt', 'intermediate', 910),
  ('v435', 'qualify', 'Phải cày thêm cái bằng tiếng Nhật mới QUALIFY cho cái vị trí sang Tokyo làm việc của công ty.', 'Đủ điều kiện, đủ tư cách', 'intermediate', 940),
  ('v436', 'reasonable', 'Cái quán lẩu này giá cả khá REASONABLE, đồ ăn lại tươi, hèn gì lúc nào cũng đông nghịt khách.', 'Hợp lý, giá cả phải chăng', 'beginner', 855),
  ('v437', 'struggle', 'Sáng nào tôi cũng phải STRUGGLE với cái báo thức, tắt đi bật lại 5 lần mới chịu dậy nổi.', 'Vật lộn, đấu tranh', 'beginner', 880),
  ('v438', 'thorough', 'Trước khi dắt xe ra khỏi bãi, nhớ check THOROUGH xem có bị trầy xước chỗ nào không kẻo mất tiền oan.', 'Kỹ lưỡng, thấu đáo', 'intermediate', 960),
  ('v439', 'unique', 'Cái phong cách ăn mặc của ông đúng là UNIQUE thật, ra đường đảm bảo không sợ đụng hàng với ai luôn.', 'Độc nhất, độc đáo', 'beginner', 860),
  ('v440', 'whisper', 'Hai đứa nó cứ WHISPER với nhau trong góc lớp, nhìn là biết đang có ''biến'' gì to lắm rồi.', 'Thì thầm', 'beginner', 830)
on conflict (id) do update set word = excluded.word, scenario = excluded.scenario,
  translation_hint = excluded.translation_hint, level = excluded.level, elo = excluded.elo;

insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v441', 'annoying', 'Mấy cái tin nhắn rác mời chào mua nhà, chứng khoán lúc giữa trưa thật sự ANNOYING vãi chưởng.', 'Làm phiền, khó chịu', 'beginner', 820),
  ('v442', 'believe', 'Tôi không thể BELIEVE nổi là thằng bạn thân mình lại đi tin mấy cái lời ''thả thính'' dạo trên mạng.', 'Tin tưởng', 'beginner', 800),
  ('v443', 'critical', 'Đây là giai đoạn CRITICAL của dự án, sai một li là đi một dặm nên anh em cẩn thận giùm cái.', 'Quan trọng, nguy cấp, phê bình', 'intermediate', 970),
  ('v444', 'delighted', 'Mẹ tôi cực kỳ DELIGHTED khi thấy tôi đem về tặng mẹ một bó hoa vào ngày 8/3, dù mẹ mắng tôi tốn tiền.', 'Vui mừng, hài lòng', 'beginner', 890),
  ('v445', 'frustrated', 'Cảm giác FRUSTRATED nhất là khi đang chuẩn bị thanh toán thì app ngân hàng bị lỗi bảo trì, đứng hình luôn.', 'Bực bội, nản lòng', 'beginner', 870),
  ('v446', 'genuine', 'Tìm được một người bạn GENUINE trong cái thời đại vật chất này khó hơn cả tìm kim đáy bể.', 'Thật lòng, chân thành', 'beginner', 880),
  ('v447', 'hesitate', 'Đừng HESITATE khi muốn nói lời xin lỗi, để lâu quá là cái ''tôi'' nó to lên rồi khó nói lắm.', 'Do dự, ngập ngừng', 'beginner', 825),
  ('v448', 'influence', 'Mấy cái video trên TikTok có INFLUENCE cực lớn đến gu thời trang của giới trẻ bây giờ.', 'Ảnh hưởng, tác động', 'intermediate', 915),
  ('v449', 'urgent', 'Ba tôi gọi điện báo có việc URGENT ở quê nên tôi phải bắt xe về gấp ngay trong đêm.', 'Khẩn cấp', 'beginner', 845),
  ('v450', 'valuable', 'Những người bạn dám nói thẳng cái sai của mình mới là những người VALUABLE nhất.', 'Quý giá, có giá trị', 'beginner', 855),
  ('v451', 'appropriate', 'Đi đám cưới mà mặc quần short áo ba lỗ thì thật sự không APPROPRIATE tí nào đâu ông nội.', 'Phù hợp, thích hợp', 'intermediate', 960),
  ('v452', 'behave', 'Ra mắt nhà bạn gái thì nhớ BEHAVE cho nó đàng hoàng, đừng có hở tí là văng tục như lúc ở với anh em.', 'Cư xử, ăn ở', 'beginner', 820),
  ('v453', 'coincidence', 'Đúng là một cái COINCIDENCE kỳ lạ, vừa mới nhắc đến tên hắn xong là hắn gọi điện tới luôn.', 'Sự trùng hợp ngẫu nhiên', 'intermediate', 980),
  ('v454', 'determined', 'Thấy bồ cũ có người yêu mới, tôi DETERMINED phải giảm cân để cho bả thấy bả đã đánh mất cái gì.', 'Quyết tâm, kiên quyết', 'beginner', 880),
  ('v455', 'encourage', 'Mẹ tôi luôn ENCOURAGE tôi theo đuổi đam mê, miễn là đừng có về nhà xin tiền mẹ là được.', 'Khuyến khích, động viên', 'beginner', 860),
  ('v456', 'familiar', 'Cái quán cà phê này nhìn FAMILIAR quá, hình như đây là nơi mình bị người yêu cũ đá thì phải.', 'Quen thuộc', 'beginner', 810),
  ('v457', 'generous', 'Ông bà chủ trọ nhà tôi cực kỳ GENEROUS, Tết nào cũng bớt cho nửa tháng tiền phòng lấy lộc.', 'Hào phóng, rộng lượng', 'beginner', 835),
  ('v458', 'hesitate', 'Thấy gái xinh thì cứ lại gần mà làm quen, đừng có HESITATE mãi kẻo thằng khác nó hốt mất.', 'Do dự, ngập ngừng', 'beginner', 825),
  ('v459', 'imitate', 'Đứa em tôi nó suốt ngày IMITATE cái giọng của tôi để đi lừa bố mẹ, nhìn mà ghét.', 'Bắt chước, nhại lại', 'intermediate', 940),
  ('v460', 'jealous', 'Mỗi lần thấy tôi đi chơi với bạn nữ khác là người yêu tôi lại JEALOUS ra mặt luôn.', 'Ghen tị, ghen tuông', 'beginner', 830),
  ('v461', 'knowledgeable', 'Ba tôi rất KNOWLEDGEABLE về xe cộ, xe hỏng chỗ nào chỉ cần nghe tiếng máy là biết ngay.', 'Am hiểu, có kiến thức rộng', 'intermediate', 950),
  ('v462', 'limit', 'Tửu lượng của tôi có LIMIT thôi, mấy ông đừng có ép tôi uống thêm nữa kẻo tôi ''huệ'' tại chỗ.', 'Giới hạn', 'beginner', 815),
  ('v463', 'motivate', 'Cái bụng mỡ chính là thứ duy nhất MOTIVATE tôi xách giày ra sân đá bóng mỗi cuối tuần.', 'Thúc đẩy, tạo động lực', 'beginner', 860),
  ('v464', 'notice', 'Tôi vừa mới NOTICE là nãy giờ tôi đang mặc áo trái đi ngoài đường, nhục không để đâu cho hết.', 'Để ý thấy, nhận ra', 'beginner', 810),
  ('v465', 'obvious', 'Lý do bả đòi chia tay quá OBVIOUS rồi: bả có mối khác ngon hơn, thế thôi.', 'Rõ ràng, hiển nhiên', 'beginner', 815),
  ('v466', 'patient', 'Muốn tán đổ crush thì phải PATIENT, chứ mới nhắn tin 2 ngày đã đòi yêu thì bả chạy mất dép.', 'Kiên nhẫn', 'beginner', 825),
  ('v467', 'quarrel', 'Mới sáng ra đã nghe thấy nhà hàng xóm QUARREL về việc ai là người đi đổ rác, mệt mỏi thật.', 'Cãi vã, tranh chấp', 'intermediate', 930),
  ('v468', 'reasonable', 'Cái shop này bán đồ giá cực kỳ REASONABLE, phù hợp với túi tiền của sinh viên nghèo như tôi.', 'Hợp lý, phải chăng', 'beginner', 855),
  ('v469', 'stubborn', 'Con mèo nhà tôi STUBBORN lắm, bảo nó xuống khỏi bàn mà nó cứ lỳ ra đó nhìn mình khinh bỉ.', 'Bướng bỉnh, lỳ lợm', 'beginner', 860),
  ('v470', 'temporary', 'Đừng lo, thất nghiệp chỉ là TEMPORARY thôi, lo mà học thêm skill mới đi rồi việc sẽ tới.', 'Tạm thời', 'beginner', 870),
  ('v471', 'urgent', 'Đang đi vệ sinh mà sếp gọi điện báo có việc URGENT thì đúng là một trải nghiệm đau khổ.', 'Khẩn cấp', 'beginner', 845),
  ('v472', 'vague', 'Câu trả lời ''Để em xem đã'' của bồ thường rất VAGUE, đa phần là bả không muốn đi rồi.', 'Mơ hồ, không rõ ràng', 'intermediate', 910),
  ('v473', 'willing', 'Tôi luôn WILLING đi nhậu nếu có ai đó bao, còn chia tiền thì để tôi xem lại lịch đã nha.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v474', 'accurate', 'Cái cân này có vẻ không ACCURATE lắm, hôm qua tôi cân 70kg mà nay nó nhảy lên 75kg là sao?', 'Chính xác', 'beginner', 880),
  ('v475', 'believable', 'Ông bảo ông đi làm muộn vì ''cứu người qua đường'' nghe chẳng BELIEVABLE tí nào đâu.', 'Có thể tin được', 'beginner', 815),
  ('v476', 'convenient', 'Cái app này CONVENIENT thật sự, đặt một cái là 15 phút sau đồ ăn đã ship tới tận cửa.', 'Tiện lợi', 'beginner', 820),
  ('v477', 'dependable', 'Trong nhóm bạn, lúc nào cũng cần một đứa DEPENDABLE để nó đứng ra lo liệu mọi thứ khi đi du lịch.', 'Đáng tin cậy', 'intermediate', 930),
  ('v478', 'effective', 'Uống nước chanh mật ong là cách EFFECTIVE nhất để trị đau họng sau một đêm hát karaoke cháy máy.', 'Hiệu quả', 'beginner', 850),
  ('v479', 'grateful', 'Tôi rất GRATEFUL vì cuối tháng hết tiền vẫn được thằng bạn thân cho ăn ké mì tôm.', 'Biết ơn', 'beginner', 860),
  ('v480', 'honest', 'Nói HONEST nhé, cái váy này mặc vào trông bà như cái bánh chưng vậy.', 'Thành thật', 'beginner', 810)
on conflict (id) do update set word = excluded.word, scenario = excluded.scenario,
  translation_hint = excluded.translation_hint, level = excluded.level, elo = excluded.elo;

insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v481', 'ignore', 'Cách tốt nhất để giữ tâm hồn thanh tịnh là IGNORE mấy cái lời drama, bóc phốt nhảm nhí trên Facebook.', 'Phớt lờ, lờ đi', 'beginner', 820),
  ('v482', 'intention', 'Tôi biết INTENTION của ông là muốn giúp bả, nhưng cách ông làm chỉ khiến bả thấy bị làm phiền thêm thôi.', 'Ý định, mục đích', 'intermediate', 910),
  ('v483', 'manage', 'Cuối tháng mà tài khoản còn 200k thì phải biết MANAGE chi tiêu cực khéo mới sống sót được đến ngày nhận lương.', 'Quản lý, xoay xở', 'beginner', 850),
  ('v484', 'necessary', 'Mua thêm cái sạc dự phòng là cực kỳ NECESSARY cho mấy chuyến đi phượt xa, không là điện thoại hết pin giữa đường là mệt.', 'Cần thiết', 'beginner', 840),
  ('v485', 'optimistic', 'Dù bị crush từ chối nhưng hắn vẫn rất OPTIMISTIC, bảo rằng ''chắc tại bả đang thử thách lòng kiên nhẫn của mình thôi''.', 'Lạc quan', 'beginner', 840),
  ('v486', 'partial', 'Đây mới chỉ là một PARTIAL sự thật thôi, đợi khi nào ông biết hết cả câu chuyện thì ông mới thấy nó sốc cỡ nào.', 'Một phần, thiên vị', 'beginner', 830),
